    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Residência da ETC localizada ao lado do campus em Bournemouth, com capacidade para até 60 estudantes internacionais; lounge estudantil com TV e jogos, Wi-Fi gratuito, CCTV e equipe no local; quarto com cama, guarda-roupa, cômoda e aquecimento central.</p><p>Apartamentos self-catering de 2 e 3 quartos a poucos minutos a pé da escola, indicados para grupos de amigos ou familiares e também disponíveis para uso exclusivo de um único estudante. A GSE não publica preço para esta opção: o valor é informado sob consulta conforme o período da viagem. A escola também intermedia hotéis de 3, 4 e 5 estrelas, igualmente sob consulta. Transfer de aeroporto ida e volta €50, mais €15 por acompanhante no mesmo voo; chegadas entre 22h e 6h têm transfer obrigatório de €30 somente ida. Seguro médico e de viagem internacional €12 por semana. Taxa de inscrição da escola €50 e material do curso €35 (cobradas no curso, não na acomodação). Fonte: GSE Adult, Family Programmes and 50 plus Courses and Accommodation Price List 2026 (english-malta.com).</p>','["Perto da Escola", "Lounge Social", "TV", "Wi-Fi", "CCTV", "Equipe no Local", "Aquecimento", "Ideal para famílias e grupos que preferem privacidade e cozinhar"]'::jsonb,'["Menos indicado para quem busca imersão com família local"]'::jsonb);
