    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Família anfitriã da LSI Boston, cuidadosamente selecionada para oferecer um ambiente acolhedor e seguro; inclui refeições diárias e serviço de lavanderia; ótima oportunidade para praticar o idioma no dia a dia e vivenciar a cultura local.</p><p>Suplementos e condições: Suplemento de alta temporada: EUR 45/semana (26/jun a 30/ago/2026); Suplemento banheiro privativo: EUR 80/semana; Suplemento dieta especial: EUR 70/semana; Noite extra: EUR 30.</p><p>Alta temporada de 26/jun a 30/ago/2026: acrescente €45 por semana ao valor base; fora desse período vale o preço base. Banheiro privativo €80 por semana e dieta especial €70 por semana. Noite extra: €30 em quarto compartilhado e €38 em quarto individual na baixa temporada, €36 e €60 na alta. As famílias ficam de 5 a 20 minutos a pé da escola ou a um curto trajeto de ônibus. Transfer de aeroporto ida e volta €50, mais €15 por acompanhante no mesmo voo; chegadas entre 22h e 6h têm transfer obrigatório de €30 somente ida. Seguro médico e de viagem internacional €12 por semana. Taxa de inscrição da escola €50 e material do curso €35 (cobradas no curso, não na acomodação). Fonte: GSE Adult, Family Programmes and 50 plus Courses and Accommodation Price List 2026 (english-malta.com).</p>','["Anfitriões Licenciados", "Refeições Incluídas", "Serviço de Lavanderia", "Ideal para amigos que viajam juntos e querem imersão cultural"]'::jsonb,'["Menos indicado para quem busca total independência"]'::jsonb);
