    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Quarto compartilhado (twin ou triplo, conforme disponibilidade). Banheiro compartilhado (limpo diariamente). Regime de café da manhã incluído (buffet). Inclui: ar-condicionado/aquecimento, Wi-Fi e uso da cozinha comunitária. Não inclui: almoço e jantar.</p><p>Suplementos e condições: Suplemento de alta temporada: EUR 60/semana (26/jun a 30/ago/2026); Noite extra: EUR 30; Depósito caução (reembolsável): EUR 50.</p><p>Alta temporada de 26/jun a 30/ago/2026: acrescente €60 por semana ao valor base; fora desse período vale o preço base. Noite extra na residência: €30 por noite em quarto compartilhado e €55 em quarto individual na baixa temporada, €37 e €65 na alta. Caução de €50 em dinheiro cobrada no check-in e devolvida no check-out. Ar-condicionado funciona com moedas no verão, Wi-Fi é gratuito, os banheiros são compartilhados por cerca de 4 alunos no inverno e 6 no verão, os quartos são limpos em dias alternados e roupa de cama e toalhas trocadas uma vez por semana. Transfer de aeroporto ida e volta €50, mais €15 por acompanhante no mesmo voo; chegadas entre 22h e 6h têm transfer obrigatório de €30 somente ida. Seguro médico e de viagem internacional €12 por semana. Taxa de inscrição da escola €50 e material do curso €35 (cobradas no curso, não na acomodação). Fonte: GSE Adult, Family Programmes and 50 plus Courses and Accommodation Price List 2026 (english-malta.com).</p>','["Residência da Gateway School of English (GSE) ao lado da escola em St. Julian''s/San Gwann, a apenas 2-3 minutos a pé da sala de aula; quartos totalmente climatizados (ar-condicionado e aquecimento), Wi-Fi gratuito em toda a propriedade, cozinha comunitária moderna para preparo de refeições, área de convívio e pátio; café da manhã em buffet incluído.", "Ideal para quem viaja em grupo e busca ambiente internacional"]'::jsonb,'["Menos indicado para quem exige banheiro privativo"]'::jsonb);
